function cxLoad(tid){ try { return JSON.parse(localStorage.getItem('gatcx_' + tid) || '{}') || {} } catch (e) { return {} } }
function cxSave(tid, o){ try { localStorage.setItem('gatcx_' + tid, JSON.stringify(o)) } catch (e) {} }
function cxRing(root){
  var secs = root.querySelectorAll('.cx-sec'), n = root.querySelectorAll('.cx-sec.done').length, C = 2 * Math.PI * 26;
  var fg = root.querySelector('.cx-ring-fg'); if (fg) fg.style.strokeDasharray = (secs.length ? C * n / secs.length : 0) + ' ' + C;
  var rt = root.querySelector('.cx-ring-t'); if (rt) rt.textContent = n + '/' + secs.length;
  root.querySelectorAll('.cx-chip').forEach(function(ch){ var s = root.querySelector('#' + ch.getAttribute('data-target')); ch.classList.toggle('ok', !!(s && s.classList.contains('done'))); });
}
function cxDrillHtml(tid){
  var qs = (GAT_QCARDS[tid] || []).slice().sort(function(){ return Math.random() - 0.5 }).slice(0, 6);
  return qs.map(function(c){ return '<button class="cx-dq cx-item" data-cx="dq">' + c.f + '<div class="a"><b>' + c.m + '</b>' + (c.s ? ' ' + c.s : '') + '</div></button>'; }).join('');
}

/* Attach the exact GAT handlers to a rendered cheat-sheet root */
export function initGatCheat(root){
  if (!root || root.dataset.gatcx) return;
  root.dataset.gatcx = '1';

  root.addEventListener('click', function(e){
    var t = e.target.closest('[data-cx]'); if (!t) return;
    var rc = t.closest('.cx'), a = t.getAttribute('data-cx'); if (!rc) return;
    if (a === 'pdf'){ window.print(); }
    else if (a === 'cover'){
      var on = !rc.classList.contains('cx-cover'); rc.classList.toggle('cx-cover', on); t.setAttribute('aria-pressed', on ? 'true' : 'false');
      rc.querySelectorAll('.cx-ans.shown').forEach(function(x){ x.classList.remove('shown'); });
    }
    else if (a === 'reveal'){ if (rc.classList.contains('cx-cover')) t.classList.toggle('shown'); }
    else if (a === 'done'){
      var sec = t.closest('.cx-sec'), tid = rc.getAttribute('data-tid'), st = cxLoad(tid);
      sec.classList.toggle('done');
      if (sec.classList.contains('done')) st[sec.getAttribute('data-key')] = 1; else delete st[sec.getAttribute('data-key')];
      cxSave(tid, st); cxRing(rc);
    }
    else if (a === 'view'){
      var g = t.closest('.cx-group'); g.classList.toggle('v-table', t.getAttribute('data-v') === 'table');
      g.querySelectorAll('.cx-seg button').forEach(function(b){ b.classList.toggle('on', b === t); });
    }
    else if (a === 'step'){ t.classList.toggle('ok'); }
    else if (a === 'flip'){ t.classList.toggle('flipped'); }
    else if (a === 'trick'){
      var sec2 = t.closest('.cx-sec'), n = t.getAttribute('data-i');
      sec2.querySelectorAll('.cx-tile').forEach(function(x){ x.classList.remove('on'); });
      t.classList.add('on'); t.classList.add('seen');
      sec2.querySelectorAll('.cx-tdet').forEach(function(d){ d.classList.toggle('show', d.getAttribute('data-d') === n); });
    }
    else if (a === 'sol'){
      var box = t.parentNode.querySelector('.cx-exs'), open = box && box.hasAttribute('hidden');
      if (box){ if (open) box.removeAttribute('hidden'); else box.setAttribute('hidden', ''); }
      t.textContent = open ? 'Hide solution' : 'Show solution';
    }
    else if (a === 'dq'){ t.classList.toggle('open'); }
    else if (a === 'shuffle'){
      var host = rc.querySelector('.cx-drill'); if (host) host.innerHTML = cxDrillHtml(rc.getAttribute('data-tid'));
    }
    else if (a === 'nav'){
      var target = document.getElementById(t.getAttribute('data-target')); if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  });

  root.addEventListener('keydown', function(e){
    if ((e.key === 'Enter' || e.key === ' ') && e.target.matches && e.target.matches('.cx-step,.cx-flip')){ e.preventDefault(); e.target.click(); }
  });

  root.addEventListener('input', function(e){
    if (!e.target.classList || !e.target.classList.contains('cx-q')) return;
    var rc = e.target.closest('.cx'), q = e.target.value.toLowerCase().trim();
    rc.querySelectorAll('.cx-item').forEach(function(it){ it.classList.toggle('cx-hide', !!q && it.textContent.toLowerCase().indexOf(q) < 0); });
    rc.querySelectorAll('.cx-sec').forEach(function(s){
      var items = s.querySelectorAll('.cx-item'); if (!items.length) return;
      var vis = Array.prototype.some.call(items, function(i){ return !i.classList.contains('cx-hide'); });
      s.classList.toggle('cx-empty', !!q && !vis);
    });
  });

  /* restore persisted section ticks + ring */
  var tid = root.getAttribute('data-tid');
  if (tid){
    var st = cxLoad(tid);
    root.querySelectorAll('.cx-sec').forEach(function(s){ if (st[s.getAttribute('data-key')]) s.classList.add('done'); });
    cxRing(root);
  }
}
